pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;

    function setUp() public { c = new RoundFactory(); }

    function testFuzz_property(address caller, address newOwner) public {
        if (newOwner == address(0)) return;

        c.initialize();

        if (caller == address(this)) return;

        bool ok;
        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}
